import re
import functools

# SemVer 2.0.0 regex: optional leading 'v', then MAJOR.MINOR.PATCH,
# optional prerelease (-...), optional build (+...).
_SEMVER_RE = re.compile(
    r'^v?'
    r'(\d+)'                       # MAJOR
    r'\.(\d+)'                     # MINOR
    r'\.(\d+)'                     # PATCH
    r'(?:-(-[\w.-]+(?:\+[\w.-]+)?)?)?'   # optional prerelease (+build inside)
    r'$'
)

# Regex for prerelease identifiers (split by '.')
_PRERELEASE_RE = re.compile(r'^([\w]+)$')


def _parse_version(raw: str):
    """Return (major, minor, patch, pre_parts, has_build) or raise ValueError."""
    m = _SEMVER_RE.match(raw)
    if not m:
        raise ValueError(f"Invalid semantic version string: {raw!r}")

    major_s, minor_s, patch_s, pre_s = m.group(1), m.group(2), m.group(3), m.group(4)

    # Validate leading zeros: each numeric part must not start with '0' unless it IS '0'
    for label, val_s in [("MAJOR", major_s), ("MINOR", minor_s), ("PATCH", patch_s)]:
        if len(val_s) > 1 and val_s[0] == '0':
            raise ValueError(f"Invalid leading zero in {label}: {val_s}")

    major, minor, patch = int(major_s), int(minor_s), int(patch_s)

    # Parse prerelease
    pre_parts = ()
    has_build = False
    if pre_s is not None:
        has_build = '+' in pre_s
        # Split off build version if present
        pre_str = pre_s.split('+')[0]
        pre_parts = tuple(pre_str.split('.'))

        # Validate each identifier
        for ident in pre_parts:
            if not ident:
                raise ValueError(f"Empty prerelease identifier in {raw!r}")
            if ident.isdigit():
                # Numeric: no leading zeros (already checked by regex? Let's validate)
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Invalid leading zero in prerelease numeric identifier: {ident!r}")
                # Just check it's purely digits (regex already ensures \w+)
            elif ident.startswith('0') and ident[0] != '0':
                # Alphanumeric starting with 0 is fine per SemVer spec
                pass

    return major, minor, patch, pre_parts, has_build


def _pre_compare(a_parts, b_parts):
    """Compare two prerelease tuples. Return -1, 0, or 1.
    Per SemVer: fewer fields < more fields if all preceding are equal.
    Numeric < alphanumeric.
    """
    for a, b in zip(a_parts, b_parts):
        if a == b:
            continue
        a_is_num = a.isdigit()
        b_is_num = b.isdigit()

        if a_is_num and b_is_num:
            return int(a) - int(b)
        elif a_is_num:
            # numeric identifiers always have lower precedence than alphanumeric
            return -1
        elif b_is_num:
            return 1
        else:
            # both alphanumeric: lexicographic
            return -1 if a < b else 1

    # All common parts equal: fewer fields < more fields
    if len(a_parts) < len(b_parts):
        return -1
    elif len(a_parts) > len(b_parts):
        return 1
    return 0


def _version_key(version_str: str):
    """Return a key tuple for sorting/comparison.
    Key: (major, minor, patch, pre_flag, pre_comparison)
    pre_flag: 0 if prerelease exists, 1 if no prerelease (so no-prerelease > prerelease)
    pre_comparison: key for prerelease parts (None if none)
    """
    major, minor, patch, pre_parts, has_build = _parse_version(version_str)

    if pre_parts:
        # Use a list of comparable items
        # Numeric identifiers become int, alphanumeric stay str.
        # We need a tuple where we can compare mixed types.
        # Strategy: use tuples (type_tag, value) where type_tag 0=int, 1=str
        pre_key = []
        for ident in pre_parts:
            if ident.isdigit():
                pre_key.append((0, int(ident)))
            else:
                pre_key.append((1, ident))
        return (major, minor, patch, 0, tuple(pre_key))
    else:
        # No prerelease -> greater than any with prerelease
        return (major, minor, patch, 1, ())


def compare(a: str, b: str) -> int:
    """Compare two semantic version strings.

    Returns:
        -1 if a < b, 0 if equal precedence, 1 if a > b.
    """
    key_a = _version_key(a)
    key_b = _version_key(b)

    if key_a < key_b:
        return -1
    elif key_a > key_b:
        return 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    """Return a new list sorted by precedence (ascending).

    Versions with equal precedence retain their original order (stable sort).
    """
    return sorted(versions, key=_version_key)

